(() => {
 const data=window.SCHOOL_DATA,main=document.getElementById('main'),params=new URLSearchParams(location.search),all=data.lessons||[];
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const url=l=>'lessons.html?lesson='+encodeURIComponent(l.id),read=l=>'reader.html?lesson='+encodeURIComponent(l.id)
const media=window.SCHOOL_MEDIA||{lessons:{},topics:{}},mediaBlock=(list,title,note,id='')=>list&&list.length?`<section class="media-links"${id?` id="${id}"`:''}><h2>${esc(title)}</h2>${note?`<p>${esc(note)}</p>`:''}<ul>${list.map(m=>`<li><a href="${esc(m.url)}" target="_blank" rel="noopener"><span class="media-kind media-${m.type}">${m.type==='padlet'?'Padlet':'影片'}</span><span class="media-label">${esc(m.label)}</span>${m.star?'<span class="media-star">推薦</span>':''}<span class="media-go" aria-hidden="true">↗</span></a></li>`).join('')}</ul></section>`:'';
 const cover=(l,thumb=false)=>l.cover?data.assets[l.cover][thumb?'thumb':'src']:l.coverPage;
 const term=l=>`${l.year}${l.semester===1?'上':'下'}`;
 const heading=(title,description,detail=false)=>`<header class="page-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span>${detail?'<a href="lessons.html">教案書屋</a><span>/</span>':''}<span>${esc(title)}</span></div><h1>${esc(title)}</h1><p>${esc(description)}</p></header>`;
 // 一課的整合資料：對應的課程單元就是教材；單元連到的活動紀錄、學生作品和學習步驟卡算作品；照片合併後去重；Padlet 與影片分開列
 const byId=id=>data.resources.find(r=>r.id===id),unitOf=l=>l?.resource?byId(l.resource):null;
 const storiesOf=u=>u?u.related.map(byId).filter(r=>r&&r.section==='課程與教材'&&['活動紀錄','學生作品'].includes(r.type)):[];
 const kit=(l,u=unitOf(l))=>{const stories=storiesOf(u),linked=new Set([u?.id,...stories.map(s=>s.id)].filter(Boolean)),list=l?media.lessons[l.id]||[]:[];return {unit:u,stories,journeys:(data.journeys||[]).filter(j=>(l&&j.lessons.includes(l.id))||j.resources.some(id=>linked.has(id))),photos:[...new Set([...(l?.photos||[]),...(u?.photos||[]),...stories.flatMap(s=>s.photos)])].filter(id=>data.assets[id]),padlets:list.filter(m=>m.type==='padlet'),videos:list.filter(m=>m.type!=='padlet')};};
 const works=k=>k.stories.length+k.journeys.length;
 const kitLine=(k,unit=true)=>{const b=[unit&&k.unit&&'教材',k.photos.length&&`照片 ${k.photos.length}`,works(k)&&`作品 ${works(k)}`,k.padlets.length&&`Padlet ${k.padlets.length}`,k.videos.length&&`影片 ${k.videos.length}`].filter(Boolean);return b.length?`<p class="lesson-kit">${b.map(x=>`<span>${esc(x)}</span>`).join('')}</p>`:'';};
 const card=l=>`<article class="resource-card visual-card lesson-card"><a class="card-image ${l.cover?'':'image-contain'}" href="${url(l)}" tabindex="-1" aria-hidden="true"><img src="${esc(cover(l,true))}" alt="" loading="lazy"></a><div class="card-copy"><span class="type-label">${esc(l.topic)}</span><h3><a href="${url(l)}">${esc(l.title)}</a></h3><div class="meta-line"><span>${term(l)}</span><span>${esc(l.course)}</span></div><p>${esc(l.summary)}</p>${kitLine(kit(l))}<div class="card-bottom"><a class="text-link" href="${url(l)}">打開這份教案 →</a><span>${l.end-l.start+1} 頁${l.periods?' · '+l.periods+' 節':''}</span></div></div></article>`;
 document.querySelector('a[href="lessons.html"]')?.setAttribute('aria-current','page');
 const selected=all.find(l=>l.id===params.get('lesson'));
 if(params.has('lesson')){
  if(!selected){main.innerHTML=heading('換一堂課，繼續探索','回到教案書屋，挑選一個主題開始。')+'<a class="button" href="lessons.html">返回教案書屋</a>';return;}
  const l=selected,k=kit(l),pages=l.end-l.start+1,topicMedia=media.topics[l.topic]||[];document.title=l.title+'｜Salimpo 教案書屋';
  const nav=[['lesson-plan',`教案 ${pages} 頁`],k.unit&&['lesson-material','教材'],k.photos.length&&['lesson-photos',`課程照片 ${k.photos.length}`],works(k)&&['lesson-works',`學生作品 ${works(k)}`],k.padlets.length&&['lesson-padlet',`Padlet ${k.padlets.length}`],k.videos.length&&['lesson-videos',`影片 ${k.videos.length}`]].filter(Boolean);
  const workCard=(href,img,type,title,meta)=>`<article class="resource-card visual-card"><a class="card-image" href="${href}" tabindex="-1" aria-hidden="true"><img src="${esc(img)}" alt="" loading="lazy" decoding="async"></a><div class="card-copy"><span class="type-label">${esc(type)}</span><h3><a href="${href}">${esc(title)}</a></h3><div class="meta-line">${meta.filter(Boolean).map(m=>`<span>${esc(m)}</span>`).join('')}</div></div></article>`;
  const material=k.unit?`<section class="kit-section" id="lesson-material"><div class="album-heading"><div><p class="eyebrow">TEACHING MATERIALS</p><h2>教材：${esc(k.unit.title)}</h2></div><a class="text-link" href="resource.html?id=${esc(k.unit.id)}">看單元頁 →</a></div><p class="kit-lead">${esc(k.unit.summary)}</p><dl class="kit-unit">${k.unit.sections.map(s=>`<div><dt>${esc(s.title)}</dt><dd>${esc(s.text)}</dd></div>`).join('')}</dl></section>`:'';
  const photos=k.photos.length?`<section class="story-album kit-section" id="lesson-photos"><div class="album-heading"><div><p class="eyebrow">MOMENTS IN CLASS</p><h2>課程照片</h2></div><p>${k.photos.length} 張影像 · 點照片可以放大</p></div><div class="photo-gallery" id="photo-gallery"></div><button type="button" class="pill gallery-more" id="gallery-more">再看更多照片</button></section>`:'';
  const workList=works(k)?`<section class="kit-section" id="lesson-works"><div class="album-heading"><div><p class="eyebrow">STUDENT WORKS</p><h2>學生作品與學習紀錄</h2></div><p>${works(k)} 項 · 從過程到作品</p></div><div class="resource-grid">${k.stories.map(s=>workCard(`resource.html?id=${esc(s.id)}`,data.assets[s.cover]?.thumb||'',s.type,s.title,[term(s),`${s.photos.length} 張影像`])).join('')}${k.journeys.map(j=>workCard(`journeys.html#${esc(j.id)}`,data.assets[j.steps.find(st=>data.assets[st.photo])?.photo]?.thumb||'','學習步驟卡',j.title,[j.term,j.band,`${j.steps.length} 個步驟`])).join('')}</div></section>`:'';
  main.innerHTML=heading(l.title,l.summary,true)+`<article class="page-body rich-story lesson-detail"><div class="story-hero ${l.cover?'':'image-contain'}"><img src="${esc(cover(l))}" alt="${esc(l.title)}的圖文內容"></div><div class="story-facts"><span>${esc(l.band)}</span><span>${term(l)}</span><span>${esc(l.course)}</span><span>${esc(l.topic)}</span>${l.periods?'<span>'+l.periods+' 節</span>':''}<span>${pages} 頁教案</span></div><nav class="kit-nav" aria-label="這一課的教案、教材與作品"><span>這一課有</span>${nav.map(([id,text])=>`<a href="#${id}">${esc(text)}</a>`).join('')}</nav><div class="story-layout"><div><section class="story-chapter"><p class="chapter-number">01 / LET'S LEARN</p><h2>這堂課，從這裡開始</h2><p>${esc(l.summary)}</p></section>${l.objectives?`<section class="story-chapter"><p class="chapter-number">02 / LEARNING GOALS</p><h2>這堂課想學會什麼？</h2><p class="lesson-excerpt">${esc(l.objectives)}</p></section>`:''}${l.vocabulary?`<section class="story-chapter"><p class="chapter-number">03 / WORDS IN OUR LIFE</p><h2>教案裡的族語與關鍵詞</h2><p class="lesson-excerpt">${esc(l.vocabulary)}</p></section>`:''}</div><aside class="story-reading"><p class="eyebrow">OPEN THIS LESSON</p><h2>走進這個主題</h2><a class="reading-entry" href="${read(l)}"><span>完整教學內容</span><strong>閱讀${esc(l.title)}教案</strong><small>${pages} 頁 · 主題內搜尋 ↗</small></a><a class="text-link" href="lessons.html">← 回教案書屋</a></aside></div><section class="lesson-pages kit-section" id="lesson-plan"><div class="album-heading"><div><p class="eyebrow">LESSON PLAN</p><h2>教案：翻開看看</h2></div><a class="text-link" href="${read(l)}">閱讀全部 ${pages} 頁 →</a></div><div class="lesson-page-preview">${[l.start,Math.min(l.end,l.start+1)].map(n=>`<a href="reader.html?lesson=${esc(l.id)}&page=${n}" aria-label="閱讀${esc(l.title)}教案第${n-l.start+1}頁"><img src="media/${esc(l.book)}/${String(n).padStart(3,'0')}.webp" alt="${esc(l.title)}教案第${n-l.start+1}頁" loading="lazy"></a>`).join('')}</div></section>${material}${photos}${workList}${mediaBlock(k.padlets,'Padlet 原板','這一課的學習歷程原板，點了會開新分頁。','lesson-padlet')}${mediaBlock(k.videos,'課程影片','點了會開新分頁。','lesson-videos')}${topicMedia.length?`<details class="kit-more"><summary>同主題「${esc(l.topic)}」的更多 Padlet 與影片（${topicMedia.length}）</summary>${mediaBlock(topicMedia,l.topic+'：更多 Padlet 原板與影片','其他學年度的學習歷程和影片，點了會開新分頁。')}</details>`:''}<section class="story-related"><h2>同一個主題，還有這些課</h2><div class="resource-grid">${all.filter(x=>x.id!==l.id&&x.topic===l.topic).slice(0,3).map(card).join('')}</div></section></article>`;
  if(k.photos.length){let shown=24;const grid=document.getElementById('photo-gallery'),more=document.getElementById('gallery-more');const draw=()=>{grid.innerHTML=k.photos.slice(0,shown).map((id,i)=>{const a=data.assets[id];return `<button type="button" class="photo-open" data-photo="${esc(id)}" data-caption="${esc(l.title)}｜課程照片 ${i+1}" aria-label="放大${esc(l.title)}照片${i+1}"><img src="${esc(a.thumb)}"${a.width&&a.height?` width="${a.width}" height="${a.height}"`:''} alt="${esc(l.title)}的課程照片" loading="lazy" decoding="async"><span>放大觀看 ↗</span></button>`;}).join('');more.hidden=shown>=k.photos.length;more.textContent=`再看更多照片（${Math.max(0,k.photos.length-shown)} 張）`;};more.onclick=()=>{shown+=24;draw();};draw();}
  // 帶錨點進來直接跳到那一段，不整頁平滑捲動
  const target=location.hash&&document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target){const root=document.documentElement;root.style.scrollBehavior='auto';target.scrollIntoView();root.style.scrollBehavior='';}
  return;
 }
 // 教材工坊：114下每個課程單元一包，點進去是那一課的整合頁；114上的教案列在下面，附 Padlet、影片與步驟卡數量
 if(params.get('view')==='materials'){
  document.title='教材工坊｜Salimpo 教案書屋';
  const bands=['低年級','中年級','高年級'],units=data.resources.filter(r=>r.type==='課程單元'),older=all.filter(l=>l.semester===1).sort((a,b)=>bands.indexOf(a.band)-bands.indexOf(b.band)||a.start-b.start);
  const unitCard=u=>{const l=all.find(x=>x.resource===u.id),href=l?url(l):'resource.html?id='+encodeURIComponent(u.id);return `<article class="resource-card visual-card lesson-card"><a class="card-image" href="${href}" tabindex="-1" aria-hidden="true"><img src="${esc(data.assets[u.cover]?.thumb||'')}" alt="" loading="lazy" decoding="async"></a><div class="card-copy"><span class="type-label">課程單元</span><h3><a href="${href}">${esc(u.title)}</a></h3><div class="meta-line"><span>${u.year}${u.semester===1?'上':'下'}</span>${u.bands.map(b=>`<span>${esc(b)}</span>`).join('')}${l?`<span>教案 ${l.end-l.start+1} 頁</span>`:''}</div><p>${esc(u.summary)}</p>${kitLine(kit(l,u),false)}<div class="card-bottom"><a class="text-link" href="${href}">${l?'打開這一包 →':'看單元內容 →'}</a></div></div></article>`;};
  const row=l=>`<li><a href="${url(l)}"><strong>${esc(l.title)}</strong><span>${esc(l.band)} · ${esc(l.course)} · 教案 ${l.end-l.start+1} 頁</span></a>${kitLine(kit(l))}</li>`;
  main.innerHTML=heading('教材工坊','每個單元的教案、教材、課程照片、學生作品、Padlet 和影片，整理成一包。')+`<div class="page-body"><section class="kit-group"><div class="album-heading"><div><p class="eyebrow">114 下學期</p><h2>${units.length} 個課程單元</h2></div><p>點一個單元，教案、教材、照片、作品、Padlet 和影片都在同一頁。</p></div><div class="resource-grid">${units.map(unitCard).join('')}</div></section><section class="kit-group"><div class="album-heading"><div><p class="eyebrow">114 上學期</p><h2>${older.length} 份教案</h2></div><p>附 Padlet 原板、課程影片和學習步驟卡。</p></div><ul class="kit-list">${older.map(row).join('')}</ul></section><a class="text-link" href="lessons.html">← 回教案書屋，依主題找全部教案</a></div>`;
  return;
 }
 document.title='按主題找教案｜Salimpo 教案書屋';
 main.innerHTML=heading('挑一個主題，走進一堂課','山林、海洋、歌謠、工藝和部落故事，找找下一堂課的靈感。')+`<div class="page-body"><nav class="lesson-topics" aria-label="教案主題"><button type="button" data-topic="" aria-pressed="true">全部主題</button>${data.lessonTopics.map(t=>`<button type="button" data-topic="${esc(t)}" aria-pressed="false">${esc(t)}</button>`).join('')}</nav><form class="filters lesson-filters" role="search" aria-label="搜尋教案"><label class="filter-field" for="lesson-query">找一堂課<input id="lesson-query" type="search" placeholder="例如：野番茄、家屋、族語"></label><label class="filter-field" for="lesson-band">年段<select id="lesson-band"><option value="">全部年段</option>${['低年級','中年級','高年級'].map(b=>`<option>${b}</option>`).join('')}</select></label><label class="filter-field" for="lesson-term">學期<select id="lesson-term"><option value="">全部學期</option><option value="1">114上學期</option><option value="2">114下學期</option></select></label></form><div class="results-top"><p id="lesson-count" class="results-count" role="status" aria-live="polite"></p><button type="button" class="reset-button" id="lesson-reset">重新探索</button></div><div id="lesson-results"></div><div id="lesson-media"></div><section class="lesson-more-books"><h2>教案旁邊的更多靈感</h2><div class="related-list"><a href="lessons.html?view=materials"><span>教材工坊：一個單元一包</span><span>教案、教材、照片、作品 ↗</span></a><a href="reader.html?book=report114a&page=555"><span>上學期評量規準與學習單</span><span>閱讀內容 ↗</span></a><a href="reader.html?book=report114b"><span>山海學習全紀錄</span><span>完整成果 ↗</span></a></div></section></div>`;
 let topic=params.get('topic')||'',query=document.getElementById('lesson-query'),band=document.getElementById('lesson-band'),semester=document.getElementById('lesson-term');query.value=params.get('q')||'';band.value=params.get('band')||'';semester.value=params.get('semester')||'';
 function draw(){const q=query.value.trim().toLocaleLowerCase(),list=all.filter(l=>(!topic||l.topic===topic)&&(!band.value||l.band===band.value)&&(!semester.value||String(l.semester)===semester.value)&&(!q||[l.title,l.summary,l.topic,l.course,l.vocabulary,l.objectives].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>b.semester-a.semester||a.start-b.start);document.getElementById('lesson-count').textContent=`找到 ${list.length} 組教案 · 共 ${all.length} 個主題單元`;document.getElementById('lesson-results').innerHTML=list.length?['低年級','中年級','高年級'].map(b=>{const rows=list.filter(l=>l.band===b);return rows.length?`<section class="lesson-band-group"><div class="album-heading"><h2>${b}的學習旅程</h2><p>${rows.length} 組教案</p></div><div class="resource-grid">${rows.map(card).join('')}</div></section>`:'';}).join(''):'<div class="empty-state"><h2>換個主題，再找找看</h2><p>試試其他關鍵字或年段。</p></div>';document.getElementById('lesson-media').innerHTML=topic?mediaBlock(media.topics[topic],topic+'：更多 Padlet 原板與影片','其他學年度的學習歷程和影片，點了會開新分頁。'):''
main.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));const u=new URL(location.href);u.search='';for(const [k,v] of [['topic',topic],['q',query.value],['band',band.value],['semester',semester.value]])if(v)u.searchParams.set(k,v);history.replaceState(null,'',u);}
 main.querySelector('form').onsubmit=e=>{e.preventDefault();draw();};query.oninput=draw;band.onchange=draw;semester.onchange=draw;main.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.topic;draw();});document.getElementById('lesson-reset').onclick=()=>{topic='';query.value='';band.value='';semester.value='';draw();};draw();
})();
